	["Horizontal Offset"] = "水平偏移", -- draft
	["Nudge the text left (negative) or right (positive) from where Blizzard places its own bar text."] = "从暴雪放置自己条文字的位置向左（负值）或向右（正值）微移文字。", -- draft
	["Vertical Offset"] = "垂直偏移", -- draft
	["Nudge the text down (negative) or up (positive)."] = "向下（负值）或向上（正值）微移文字。", -- draft
	["Font Size"] = "字体大小", -- draft
	["Text size. Default follows the status bar text font of the game (and the Fonts module)."] = "文字大小。默认跟随游戏的状态栏数值字体（以及字体模块）。", -- draft
	["Values Font"] = "数值字体", -- draft
	["The face of the health and power values on the player, target and focus frames. Shared: the Interface text's face (Look > Fonts)."] = "玩家、目标和焦点框体上生命值和能量值的字体。共享：“界面文字”的字体（外观 > 字体）。", -- draft
