	["Speed"] = "语速", -- draft
	["How fast text-to-speech reads; 0 is the voice's normal pace. Recorded lines always play at their own pace."] = "文字转语音的朗读速度；0为该声音的正常语速。录制的台词始终按自己的语速播放。", -- draft
	["Volume"] = "音量", -- draft
	["How loud text-to-speech reads. Recorded lines follow the Sound Channel's volume in the game's sound settings."] = "文字转语音的音量。录制的台词跟随游戏声音设置中音效频道的音量。", -- draft
	["Voice Per Race (optional)"] = "按种族选择声音（可选）", -- draft
